//! `wisp.rs`: one documented `pub mod` per component, including its
//! generated file, and one per subdirectory. It names no path of the
//! build machine: each `.wisp` by its path under `root` (the compiled
//! directory's parent, as sites name it), and each generated file
//! relative to `wisp.rs`, which `include!` resolves from the including
//! file's directory.

use std::fmt::Write;
use std::path::Path;

use super::tree::Dir;

/// The directory beside `wisp.rs` that holds the generated files.
const GENERATED: &str = "wisp";

/// The modules file for `tree`, whose `.wisp` files are under `root`,
/// including `shapes.rs` when the crate has a shape table.
pub(crate) fn render(tree: &Dir, root: &Path, shapes: bool) -> String {
    let mut text = String::from(
        "// Generated by vapors-compiler from the .wisp files; edit those, not this file.\n",
    );
    render_dir(tree, (root, Path::new(GENERATED)), &mut text);
    if shapes {
        text.push_str(
            "\n// The crate's shape table, beside this file.\ninclude!(\"shapes.rs\");\n",
        );
    }
    text
}

/// The `out` directory's subdirectory `wisp.rs` includes from.
pub(crate) fn generated_dir(out: &Path) -> std::path::PathBuf {
    out.join(GENERATED)
}

fn render_dir(dir: &Dir, (root, generated): (&Path, &Path), text: &mut String) {
    for file in &dir.files {
        let include = generated.join(format!("{}.rs", file.module));
        let _ = write!(
            text,
            "\n/// The component compiled from `{}`.\npub mod {} {{\n    include!({:?});\n}}\n",
            under(&file.path, root).display(),
            file.module,
            include.display().to_string()
        );
    }
    for sub in &dir.dirs {
        let _ = write!(
            text,
            "\n/// The components under `{}`.\npub mod {} {{\n",
            under(&sub.path, root).display(),
            sub.module
        );
        render_dir(sub, (root, &generated.join(&sub.module)), text);
        text.push_str("}\n");
    }
}

/// `path` under `root`: every path in the tree was found by scanning
/// under it.
fn under<'p>(path: &'p Path, root: &Path) -> &'p Path {
    path.strip_prefix(root)
        .expect("the tree is scanned under the compiled directory's parent")
}
